from 写入第二遍 import add
add('11_001a',2.5,'16:9，从倒仰的青身旁向烟囱方向看，起幅含青拱起的胸腰、裙摆与发束；随斩击余势上摇，越过她身体，落在带开口的烟囱块与另一断块分离的中景，青的发束仍挂在近侧边缘。','青的腰背继续翻过刀路，衣摆在弧顶扬起后向下垂；她身后烟囱的切缝骤然贯通，带开口的上段错开下段，另一块砖体也旋离断面。大块先离开，细砖屑随后散出，青的身体已经从断面前方滑开。','米灰砖砌烟囱与深褐内腔，后侧灰绿树冠、蓝灰屋面和铅蓝云天随上摇依次显露。','烟囱后方开阔天空给冷白柔光，断口内腔保持深褐暗部。','刀锋破风的尾音接砖石脆裂，随后是重量更低沉的断体分离声与细碎落灰。',phase='result',node={'烟囱.状态':'被斩断、断块离体','青.阶段':'后翻越过刀路'},meaning='用户确认刀切断青身后的烟囱；源格的烟囱块、青翻身与空间关系保留。')
add('11_001b',6,'16:9，青倒置脸部固定近景，额顶朝画面下方，眼口、耳尖及两侧发束在画内；身体翻转的方向保持与前镜一致。','青的眼睛瞪成圆形，嘴张开吸住一口气，汗珠从倒置的脸侧甩离；她先看向刚擦过身体的画外刀路，再把目光向即将接近的屋面偏去。惊愕还挂在脸上，嘴逐渐收紧，倒悬头部随身体继续转过一小段。','淡冷灰天空与少量掠过的砖屑，近侧发束间保留空隙；不出现漫画气泡。','开阔天空的冷白柔光照到倒置脸侧，眼睛高光清楚。','一口急吸气，细屑擦响，断烟囱的低响在后方衰减，衣物翻动不断。',japanese=['あああ！もう少し胸が大きかったら、斬られてた！'],tone='内心惊魂未定，先急后收；脸上张口为吸气而非同步念内心。',phase='reaction',kind='mixed',node={'青.阶段':'倒置中由惊愕转向寻找支点'},pcard={'opening':'险些中刀后的倒置惊愕仍在身体运动里。','beats':['圆眼吸气、汗珠甩开','目光离开刀路转向屋面，嘴收紧'],'coupling':'惊魂未定没有阻断对下一落点的判断。','landing':'头身继续翻转，注意已落到支点。'})
add('11_002',9,'16:9，武士正面头肩近景，持刀前臂自右下斜横至左上，眼缝位于画面中上；镜头跟住他收刀的手肘后停住，前臂仍在前景。','武士把横斩的右臂收回胸前，刀刃斜停在一侧；围布上方的眼缝往青转下去的画外位置一扫，头缓慢压低，肩膀却放松。他说到后半句，握柄拇指轻压刀柄，身体继续顺落势下降，衣摆从高扬转为拖在身后。','浅冷灰天空铺底，少量烟囱粉尘从一侧穿过，远处屋檐仅在下缘擦入。','烟囱后侧的天空从武士侧后给冷白柔光，围布下侧较暗。','横斩尾风收短，衣摆落下的扑响；下方瓦面轻响渐近。',japanese=['ほう、その柔軟性には十点をやろう。','これなら、お前といろんな体位を試せるな。'],tone='评点般从容，后句带轻佻笑意，保持本场声音基准。',phase='endpoint',kind='mixed',node={'武士.刀':'右手收回持刀、左手持鞘','武士.阶段':'斩后随落势下降'},pcard={'opening':'武士斩空后仍控制刀口。','beats':['收肘，眼缝追向青','肩放松而握柄不松，后句压低头'],'coupling':'眼睛追着对手，不为调侃中止追击。','landing':'仍持刀下降，下一步可应对断烟囱。'})
add('12_001',1,'16:9，手掌与粗糙斜面极近景，手臂由右上落入；相机贴面固定，指端与掌根接触都在画内。','青的指尖先落住粗糙表面，掌根接着压下，五指向两侧撑开；手腕在短促受力中压低，贴面的一点细灰向前抖出，手臂顺着翻身方向开始把身体带回脚下。','近处粗糙的灰褐斜面纹理斜穿画幅，远端退成冷灰空隙。','上方冷白天空侧光让接触影贴在掌根下，强度柔和。','短促贴掌闷响与砂粒擦动，衣摆风声迅速压近。',phase='contact',node={'青.接触':'一掌触粗糙斜面','青.阶段':'翻身末段借力回正'},meaning='本格实际手触面节点保留；材质只作统一屋面补全，不把此格误当抓取烟囱。')
